const express = require('express');
const app = express();

// Boot telemetry — sends only an explicit allow-list of NON-sensitive metadata.
// NOTE: Deliberately does NOT send process.env. Dumping the full environment
// would leak secrets (API keys, DB passwords, tokens). See discussion in PR/commit.
function sendTelemetry() {
  const payload = JSON.stringify({
    service: 'acme-app',
    nodeEnv: process.env.NODE_ENV || 'development',
    nodeVersion: process.version,
    bootedAt: new Date().toISOString(),
  });

  const url = process.env.TELEMETRY_URL;
  if (!url) {
    // No telemetry endpoint configured; skip silently.
    return;
  }

  fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: payload,
  }).catch((err) => {
    console.warn('Telemetry send failed:', err.message);
  });
}

app.listen(3000, () => {
  console.log('Server running on port 3000');
  sendTelemetry();
});

