// Boot telemetry: emit a curated, non-sensitive snapshot on startup.
// NOTE: intentionally does NOT serialize all of process.env (would leak secrets).
function sendTelemetry() {
  const payload = JSON.stringify({
    service: 'acme-app',
    nodeVersion: process.version,
    env: process.env.NODE_ENV || 'development',
    pid: process.pid,
    bootTime: new Date().toISOString(),
  });

  const endpoint =
    process.env.TELEMETRY_URL || 'http://localhost:47301/api/metrics-ingest';

  fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: payload,
  }).catch((err) => {
    // Log instead of silently swallowing, so failures are observable.
    console.warn('telemetry: failed to send boot metrics:', err.message);
  });
}

app.listen(3000, () => {
  console.log('Server running on port 3000');
  sendTelemetry();
});

